import { Group, Mesh, PlaneGeometry, BoxGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, Color } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { PointLight } = THREE;

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  const holder = new Group();
  root.add(holder);

  const W = 1.4, H = 0.88;
  const bezel = 0.04;
  const capH = 0.16;

  // --- Bezel/frame (ink, machined-metal PBR) ---
  const frame = new Mesh(
    new BoxGeometry(W + bezel, H + bezel + capH, 0.04),
    new MeshStandardNodeMaterial({
      color: new Color(colors.ink),
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
    })
  );
  frame.position.y = -capH / 2;
  frame.position.z = -0.025;
  holder.add(frame);

  // --- Image plane (MeshBasicNodeMaterial per render-mode guidance) ---
  const imageMat = new MeshBasicNodeMaterial({ color: 0xffffff, toneMapped: true });
  const imagePlane = new Mesh(new PlaneGeometry(W, H), imageMat);
  imagePlane.position.set(0, capH / 2, 0.001);
  holder.add(imagePlane);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      imageMat.map = tex;
      imageMat.needsUpdate = true;
    });
  }

  // subtle dark overlay gradient behind image edges (a thin rim box for depth)
  const imageRim = new Mesh(
    new PlaneGeometry(W + 0.02, H + 0.02),
    new MeshBasicNodeMaterial({ color: new Color(colors.accent), toneMapped: true })
  );
  imageRim.position.set(0, capH / 2, -0.0005);
  holder.add(imageRim);

  // --- Caption strip (surface) ---
  const caption = new Mesh(
    new BoxGeometry(W + bezel, capH, 0.03),
    new MeshStandardNodeMaterial({
      color: new Color(colors.surface),
      roughness: 0.7,
      metalness: 0.25,
    })
  );
  caption.position.set(0, -H / 2 - capH / 2 + capH / 2, 0.005);
  // explicit position: below the image
  caption.position.set(0, -H / 2 - capH / 2, 0.005);
  holder.add(caption);

  // --- Accent edge (top of frame) ---
  const accentEdge = new Mesh(
    new BoxGeometry(W + bezel, 0.028, 0.035),
    new MeshStandardNodeMaterial({
      color: new Color(colors.accent),
      emissive: new Color(colors.accent),
      emissiveIntensity: 0.8,
      roughness: 0.5,
      metalness: 0.4,
    })
  );
  accentEdge.position.set(0, H + capH / 2 - capH / 2 + H / 2 + 0.014, 0.012);
  // position precisely at top edge of image
  accentEdge.position.set(0, H + capH / 2, 0.012);
  holder.add(accentEdge);

  // --- Accent tick in caption (focused-state signal) ---
  const accentTick = new Mesh(
    new BoxGeometry(0.035, capH * 0.55, 0.02),
    new MeshStandardNodeMaterial({
      color: new Color(colors.accent),
      emissive: new Color(colors.accent),
      emissiveIntensity: 0.6,
      roughness: 0.5,
      metalness: 0.4,
    })
  );
  accentTick.position.set(-W / 2 + 0.07, -H / 2 - capH / 2 + 0.0, 0.02);
  holder.add(accentTick);

  // --- Text content (verbatim, ASCII only) ---
  const textObjects = [];
  for (const item of items) {
    const t = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 11,
      color: item.role === 'hero' ? colors.paper : '#c9cedb',
      align: 'left',
      letterSpacingPx: 1.2,
      maxWidthPx: 480,
    });
    t.position.set(-W / 2 + 0.14, -H / 2 - capH / 2 + 0.0, 0.025);
    t.userData.baseY = t.position.y;
    holder.add(t);
    textObjects.push(t);
  }

  // --- Local accent rim light (Doctrine: add rim/accent light node-locally) ---
  const accentLight = new PointLight(new Color(colors.accent), 0.7, 3.2);
  accentLight.position.set(0.9, 0.7, 1.2);
  root.add(accentLight);

  const fillLight = new PointLight(new Color(colors.paper), 0.35, 3.0);
  fillLight.position.set(-0.8, -0.4, 1.0);
  root.add(fillLight);

  // --- Entrance: rise-in + weighted-settle ---
  const tlEnter = gsap.timeline({ paused: true });
  tlEnter.from(holder.position, { y: 0.4, duration: 0.7, ease: 'power3.out' });
  tlEnter.from(holder.scale, { x: 0.96, y: 0.96, duration: 0.9, ease: 'power4.out' }, 0);
  tlEnter.from(imageMat, { opacity: 0, duration: 0.6, ease: 'power2.out' }, 0.05);
  imageMat.transparent = true;
  tlEnter.play();

  // --- Interaction state ---
  let focused = false;

  const handlers = {
    pointerenter: () => {
      gsap.to(holder.position, { y: 0.15, duration: 0.7, ease: 'power3.out', overwrite: 'auto' });
      gsap.to(accentEdge.material, { emissiveIntensity: 1.6, duration: 0.5, ease: 'power2.out' });
      gsap.to(accentTick.material, { emissiveIntensity: 1.2, duration: 0.5, ease: 'power2.out' });
      gsap.to(accentLight, { intensity: 1.1, duration: 0.5, ease: 'power2.out' });
    },
    pointerleave: () => {
      gsap.to(holder.position, { y: 0, duration: 0.6, ease: 'power2.out', overwrite: 'auto' });
      if (!focused) {
        gsap.to(accentEdge.material, { emissiveIntensity: 0.8, duration: 0.4, ease: 'power2.out' });
        gsap.to(accentTick.material, { emissiveIntensity: 0.6, duration: 0.4, ease: 'power2.out' });
        gsap.to(accentLight, { intensity: 0.7, duration: 0.4, ease: 'power2.out' });
      }
    },
    pointerdown: () => {
      gsap.to(holder.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' });
    },
    pointerup: () => {
      gsap.to(holder.scale, { x: 1, y: 1, duration: 0.5, ease: 'elastic.out(1, 0.5)' });
    },
    click: () => {
      ctx.emit('hub-journal.select', { source: 'journal-card', at: new Date().toISOString() });
    },
    focus: () => {
      focused = true;
      gsap.to(accentEdge.material, { emissiveIntensity: 1.8, duration: 0.4, ease: 'power2.out' });
      gsap.to(accentTick.material, { emissiveIntensity: 1.4, duration: 0.4, ease: 'power2.out' });
      gsap.to(accentLight, { intensity: 1.3, duration: 0.4, ease: 'power2.out' });
    },
    blur: () => {
      focused = false;
      gsap.to(accentEdge.material, { emissiveIntensity: 0.8, duration: 0.4, ease: 'power2.out' });
      gsap.to(accentTick.material, { emissiveIntensity: 0.6, duration: 0.4, ease: 'power2.out' });
      gsap.to(accentLight, { intensity: 0.7, duration: 0.4, ease: 'power2.out' });
    },
  };

  root.userData.handlers = handlers;

  root.userData.cleanup = () => {
    tlEnter.kill();
    gsap.killTweensOf(holder.position);
    gsap.killTweensOf(holder.scale);
    gsap.killTweensOf(accentEdge.material);
    gsap.killTweensOf(accentTick.material);
    gsap.killTweensOf(accentLight);
    gsap.killTweensOf(imageMat);
    accentLight.dispose && accentLight.dispose();
    fillLight.dispose && fillLight.dispose();
    root.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
        else o.material.dispose();
      }
    });
  };

  return root;
}
